import {weeks,sources,activities} from './data/activities.js';
import {initLearningMap} from './learning-map.js';
const $=s=>document.querySelector(s),KEY='family-lab-v1';
let storageAvailable=true,state={age:8,selected:'paper-bridge',records:{}};
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw&&typeof raw==='object'){if([6,7,8,9,10].includes(raw.age))state.age=raw.age;if(activities.some(a=>a.id===raw.selected))state.selected=raw.selected;for(const a of activities){const r=raw.records?.[a.id];if(r&&typeof r==='object')state.records[a.id]={done:r.done===true,checks:Array.from({length:3},(_,i)=>r.checks?.[i]===true),note:typeof r.note==='string'?r.note.slice(0,3000):'',updated:typeof r.updated==='string'?r.updated:''};}}}catch{storageAvailable=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const getActivity=()=>activities.find(a=>a.id===state.selected);
const record=()=>state.records[state.selected]||(state.records[state.selected]={done:false,checks:[false,false,false],note:'',updated:''});
let toastTimer;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;}const note=$('.storage-note');if(note)note.textContent=storageAvailable?'记录仅保存在当前浏览器；更换设备不会同步，清理浏览器会丢失。可导出留存。':'浏览器未能保存记录，内容仅在此页面有效。请导出留存后再关闭。';return storageAvailable;}
function capture(){const r=record(),area=$('#reflection');if(area)r.note=area.value;document.querySelectorAll('[data-observation]').forEach(el=>r.checks[Number(el.dataset.observation)]=el.checked);}
function navigate(id){if(!activities.some(a=>a.id===id))throw new Error('未找到该活动');capture();state.selected=id;persist();render();return{activityId:id,title:getActivity().title};}
function updateProgress(){const count=activities.filter(a=>state.records[a.id]?.done).length;$('#progressText').textContent=`完成 ${count} / 8 次练习`;$('#progressPercent').textContent=`${Math.round(count/8*100)}%`;$('#overallProgress').value=count;$('#overallProgress').textContent=`${count} / 8`;}
function render(){const a=getActivity(),r=record(),w=weeks[a.week],s=sources[a.source];$('#age').value=state.age;$('#parentHint').textContent=w.parent;
$('#weeks').innerHTML=weeks.map((w,i)=>`<button type="button" class="week ${i===a.week?'active':''}" data-week="${i}" aria-pressed="${i===a.week}"><span class="week-number">0${i+1}</span><span><strong>${w.name}</strong><small>${w.subtitle}</small></span></button>`).join('');
$('#activityChoices').innerHTML=activities.filter(x=>x.week===a.week).map((x,i)=>`<button type="button" class="choice ${x.id===a.id?'selected':''}" data-activity="${x.id}" aria-pressed="${x.id===a.id}">第${i+1}次练习${state.records[x.id]?.done?'<span class="checkmark" aria-label="已完成">✓</span>':''}</button>`).join('');
$('#activity').innerHTML=`<div class="card-top"><span class="pill">第${a.week+1}周 · ${w.name}</span><span class="duration">20分钟 · 两个人一起</span></div><h2>${a.title}</h2><p class="activity-summary">${a.summary}</p><p class="source-brief">Marble 学习依据：<a href="https://github.com/withmarbleapp/os-taxonomy/blob/main/data/topics.json#L${s.line}" target="_blank" rel="noopener">${s.zh} ↗</a><span>亲子活动由本站改编</span></p><div class="materials"><strong>准备好</strong>${a.materials}</div><div class="steps">${a.steps.map((v,i)=>`<div><span>0${i+1}</span><h3>${v[0]}</h3><p>${v[1]}</p></div>`).join('')}</div><div class="question-box"><span class="mini-label">家长这样问</span><p>“${a.question}”</p></div><p class="adaptation"><strong>${state.age}岁这样练：</strong>${a.adapt[state.age<=7?0:state.age===8?1:2]}</p>`;
$('#recordPanel').hidden=false;$('#recordPanel').innerHTML=`<div class="section-title"><h3>今天，我观察到了</h3><span>勾选实际发生的，不必全部做到</span></div><div class="observations">${a.observations.map((v,i)=>`<label><input type="checkbox" data-observation="${i}" ${r.checks[i]?'checked':''}><span>${v}</span></label>`).join('')}</div><label class="reflection-label" for="reflection">我们各自的一点发现</label><textarea id="reflection" maxlength="3000" placeholder="${esc(a.reflection)}">${esc(r.note)}</textarea><div class="actions"><button type="button" class="primary" id="complete">${r.done?'已练习 · 撤销标记':'标记这次已练习'}</button><button type="button" class="secondary" id="export">导出成长记录</button><span class="save-message" id="saveMessage">${r.done?'一次尝试已记录；掌握需要在新场景中再观察。':'勾选和文字会自动保存在本机。'}</span></div><p class="storage-note"></p>`;
$('#sourcePanel').hidden=false;$('#sourcePanel').innerHTML=`<details><summary>练习依据与准备提示</summary><div class="source-inner"><p><strong>开始前：</strong>${a.prep}</p><p><strong>对应能力：</strong>${s.zh}<br>Marble原始参考年龄 ${s.age[0]}—${s.age[1]}岁；页面按所选年龄调整练习难度，年龄不作为达标要求。</p><p>${s.summary}</p><p>${s.basis}</p><p class="original">原始条目：${s.name}<br>编号：${s.id}</p><p>活动、四周顺序、年龄调整和观察项由“一起长大”编写或改编，活动安排不由地图自动推荐，也不构成能力测评；上方地图另行呈现原始前置关系。</p><a class="source-link" href="https://github.com/withmarbleapp/os-taxonomy/blob/main/data/topics.json#L${s.line}" target="_blank" rel="noopener">查看 Marble 原始条目 ↗</a></div></details>`;
document.querySelectorAll('[data-week]').forEach(el=>el.addEventListener('click',()=>navigate(activities.find(x=>x.week===Number(el.dataset.week)).id)));
document.querySelectorAll('[data-activity]').forEach(el=>el.addEventListener('click',()=>navigate(el.dataset.activity)));
document.querySelectorAll('[data-observation]').forEach(el=>el.addEventListener('change',saveDraft));$('#reflection').addEventListener('input',saveDraft);
$('#complete').addEventListener('click',()=>{capture();record().done=!record().done;record().updated=new Date().toISOString();const done=record().done,saved=persist();render();toast(saved?(done?'这次尝试已记录，慢慢来就好。':'已取消完成标记，笔记仍保留。'):'当前浏览器无法保存，请导出记录。');});$('#export').addEventListener('click',exportRecords);updateProgress();persist();}
function saveDraft(){capture();record().updated=new Date().toISOString();$('#saveMessage').textContent=persist()?'已保存到当前浏览器':'未能保存，请导出记录';}
function exportRecords(){capture();const lines=['一起长大 · 亲子练习记录',`导出日期：${new Date().toLocaleDateString('zh-CN')} | 当前年龄：${state.age}岁`,'完成记录反映参加过练习，不代表能力评级。',''];for(const a of activities){const r=state.records[a.id];lines.push(`第${a.week+1}周 | ${a.title} | ${r?.done?'已练习':'待练习'}`);a.observations.forEach((o,i)=>lines.push(`${r?.checks?.[i]?'[✓]':'[ ]'} ${o}`));if(r?.note)lines.push(`我们的发现：${r.note}`);lines.push('');}lines.push('学习框架：Marble Skill Taxonomy v1 · © Generative Spark, Inc. (Marble)','https://github.com/withmarbleapp/os-taxonomy','数据库 ODbL 1.0；文字与活动 CC BY-SA 4.0。');const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`一起长大-成长记录-${new Date().toISOString().slice(0,10)}.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('成长记录已准备下载。');}
document.querySelectorAll('[data-case-activity]').forEach(el=>el.addEventListener('click',()=>{
 navigate(el.dataset.caseActivity);
 const target=$('#activity'); target.setAttribute('tabindex','-1'); target.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}); target.focus({preventScroll:true});
}));
$('#age').addEventListener('change',e=>{capture();state.age=Number(e.target.value);persist();render();toast(`已调整为${state.age}岁的练习提示`);});render();
initLearningMap({openActivity:navigate});
// Optional WebMCP; ordinary browser use does not depend on this API.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',e=>{if(!e.persisted)lifecycle.abort();});const tools=[{name:'list_family_activities',title:'查看亲子练习',description:'列出八个亲子活动及本浏览器中的完成状态，不含个人笔记。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length)throw new Error('不接受额外参数');return activities.map(a=>({id:a.id,week:a.week+1,title:a.title,done:!!state.records[a.id]?.done}));}},{name:'open_family_activity',title:'打开亲子练习',description:'切换到指定活动并显示步骤；不会标记完成或修改观察内容。',inputSchema:{type:'object',properties:{activityId:{type:'string',enum:activities.map(a=>a.id)}},required:['activityId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='activityId')||typeof input.activityId!=='string')throw new Error('请提供有效的 activityId');return navigate(input.activityId);}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
